INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(201778, 'ruRU', 'Мы готовы. Веди!', 'Мы готовы. Веди!', 35435),
(753, 'ruRU', 'Что? Хочешь сказать, что без меня не справишься?', '', 35435),
(195400, 'ruRU', 'Покажи мне искусственные сущности.', 'Покажи мне искусственные сущности.', 35435),
(79796, 'ruRU', 'Открыт камень шаманов: прикосновение пламени', 'Открыт камень шаманов: прикосновение пламени', 35435),
(165870, 'ruRU', '', 'Я расскажу тебе о гибели Растахана, когда захочешь послушать.', 35435),
(79799, 'ruRU', 'Открыт камень шаманов: стойкость огра', 'Открыт камень шаманов: стойкость огра', 35435),
(79798, 'ruRU', 'Открыт камень шаманов: бушующий ветер', 'Открыт камень шаманов: бушующий ветер', 35435),
(79804, 'ruRU', 'Открыт камень шаманов: прикосновение льда', 'Открыт камень шаманов: прикосновение льда', 35435),
(194274, 'ruRU', 'Я хочу телепортироваться в подземелье \"Операция \"Мехагон\".', 'Я хочу телепортироваться в подземелье \"Операция \"Мехагон\".', 35435),
(183984, 'ruRU', '|cfff2e699+$1i ед. здравомыслия|r', '|cfff2e699+$1i ед. здравомыслия|r', 35435),
(201777, 'ruRU', '', 'Я знаю, как добраться до дочери морей. Следуйте за мной.', 35435),
(79794, 'ruRU', 'Открыт камень шаманов: благословение волка', 'Открыт камень шаманов: благословение волка', 35435),
(79795, 'ruRU', 'Открыт камень шаманов: дух волка', 'Открыт камень шаманов: дух волка', 35435),
(141708, 'ruRU', 'Утомите грифона быстрым полетом. Не забывайте поддерживать эффект |TInterface\\ICONS\\INV_MISC_DESECRATED_LEATHERGLOVE.BLP:20|t |cFFFF0000|Hspell:269442|h[Крепкая хватка]|h|r!', '', 35435),
(201784, 'ruRU', 'Я сам видел: леди Джайну атакуют на море!', '', 35435),
(165241, 'ruRU', 'Ближе... Ближе...', 'Ближе... Ближе...', 35435),
(165243, 'ruRU', 'Наконец-то... примите истину тьмы.', 'Наконец-то... примите истину тьмы.', 35435),
(165245, 'ruRU', 'С каждым новым выбором вы все лучше служите мне.', 'С каждым новым выбором вы все лучше служите мне.', 35435),
(165239, 'ruRU', 'Заставьте ярость служить вам... Сделайте ненависть своим оружием.', 'Заставьте ярость служить вам... Сделайте ненависть своим оружием.', 35435),
(165246, 'ruRU', 'Взгляд бога обращает жалкие безделушки в прах.', 'Взгляд бога обращает жалкие безделушки в прах.', 35435),
(165244, 'ruRU', 'Да... вы все ближе... все ближе и ближе...', 'Да... вы все ближе... все ближе и ближе...', 35435),
(165237, 'ruRU', 'О... Вы думаете, что знаете, что такое настоящая сила.', 'О... Вы думаете, что знаете, что такое настоящая сила.', 35435);

