INSERT INTO `mount_locale` (`ID`, `locale`, `Name_lang`, `SourceText_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(468, 'ruRU', 'Императорский цийлинь', '|cFFFFD200Промоакция:|r коллекционное издание Mists of Pandaria', 'Любимцы древних правителей могу, цийлини станут верным и бесстрашным компаньоном любому наезднику.', 35435),
(1282, 'ruRU', 'Черный змей Н\'Зота', '|cFFFFD200Достижение:|r \"Сквозь глубины видений\"', 'Черные змеи Н\'Зота возвещают о скором осуществлении планов Древнего бога. Поймать такого змея способны только те служители или враги Н\'Зота, кто может войти в его видения.', 35435);

DELETE FROM `player_condition_locale` WHERE `locale` = 'ruRU' AND `VerifiedBuild`>0;
INSERT INTO `player_condition_locale` (`ID`, `locale`, `FailureDescription_lang`, `VerifiedBuild`) VALUES
(79509, 'ruRU', 'Изучите любую сущность 3-го уровня, полученную от Ржавоболтского сопротивления, другим персонажем, чтобы открыть эту сущность.', 35435),
(79518, 'ruRU', 'Изучите \"Раздор и противостояние\" 3-го уровня другим персонажем, чтобы открыть эту сущность.', 35435),
(79511, 'ruRU', 'Изучите \"Концентрированную жизненную силу\", \"Проводник жизненной силы\" или \"Дар жизни Азерот\" 3-го уровня другим персонажем, чтобы открыть эту сущность.', 35435),
(79508, 'ruRU', 'Изучите \"Кровь врага\", \"Обман времени\" или \"Сферу подавления\" 3-го уровня другим персонажем, чтобы открыть эту сущность.', 35435),
(79523, 'ruRU', 'Изучите \"Бесформенную Бездну\" 3-го уровня другим персонажем, чтобы открыть эту сущность.', 35435),
(74078, 'ruRU', 'Требуется Ашжра\'камас, Покров Решимости.', 35435),
(79512, 'ruRU', 'Изучите \"Видение совершенства\" 3-го уровня другим персонажем, чтобы открыть эту сущность.', 35435),
(79505, 'ruRU', 'Изучите \"Пространственную рябь\" 3-го уровня другим персонажем, чтобы открыть эту сущность.', 35435),
(79499, 'ruRU', 'Изучите \"Сущность радужного кристалла\", \"Чары Хранительницы жизни\" или \"Сущность жизни и смерти\" 3-го уровня другим персонажем, чтобы открыть эту сущность.', 35435),
(79522, 'ruRU', 'Изучите любую сущность 3-го уровня из жутких видений другим персонажем, чтобы открыть эту сущность.', 35435),
(79514, 'ruRU', 'Изучите любую сущность 3-го уровня, полученную от Раджани или Ульдумского союза, другим персонажем, чтобы открыть эту сущность.', 35435),
